import Foundation
import MeroKit

// The workbook's types, as the contract (`../../../logic/res/abi.json`) answers them: first
// generated by @calimero/abi-codegen from v1's ABI, kept since. The calls are the generated
// `SheetsClient` (`Generated/`, `scripts/mobile-codegen.sh` at the repo root); until the logic
// derives `AbiType` the ABI names these types without their shape, so the client answers their JSON
// and they read it (`JSONValue.decoded(as:)`).

extension Encodable {
    /// This answer as the app type `T` (one of the types below).
    public func decoded<T: Decodable>(as type: T.Type) throws -> T {
        try MeroJSON.decode(type, from: MeroJSON.encode(self))
    }

    /// This value as the generated client's type `T` (an argument), through its JSON.
    public func converted<T: Decodable>() throws -> T {
        try MeroJSON.decode(T.self, from: MeroJSON.encode(self))
    }
}

// MARK: - Types

/// One entry of the workbook's activity log: what was done, when. Keyed by
/// `"{at:020}|{author}|{nonce}"`; its author is the entry's owner stamp, and a
/// "since" query is a seek on the `at` index.
public struct ActivityData: Codable, Sendable, Equatable {
    public var at: UInt64
    /// Empty for workbook-level actions (a named range).
    public var sheetId: String
    /// `cells`, `rows`, `cols`, `sheet` or `name`.
    public var kind: String
    public var summary: String
    /// How many cells changed; `changes` holds at most [`MAX_LOGGED_CHANGES`].
    public var count: UInt32
    public var changes: [CellChange]

    public init(at: UInt64, sheetId: String, kind: String, summary: String, count: UInt32, changes: [CellChange]) {
        self.at = at
        self.sheetId = sheetId
        self.kind = kind
        self.summary = summary
        self.count = count
        self.changes = changes
    }

    enum CodingKeys: String, CodingKey {
        case at
        case sheetId = "sheet_id"
        case kind
        case summary
        case count
        case changes
    }
}

