/// A structural edit: add a row or column at a fractional position, delete
/// one by id, or restore a deleted one (an undo). Every op is one write,
/// however many cells the sheet holds.
public indirect enum AxisOp: Codable, Sendable, Equatable {
    case insertRow(AxisOp_InsertRow)
    case insertCol(AxisOp_InsertCol)
    case deleteRow(AxisOp_DeleteRow)
    case deleteCol(AxisOp_DeleteCol)
    case restoreRow(AxisOp_RestoreRow)
    case restoreCol(AxisOp_RestoreCol)

    public init(from decoder: any Decoder) throws {
        let container = try decoder.container(keyedBy: ContractCodingKey.self)
        let tag = try container.decode(String.self, forKey: ContractCodingKey("name"))
        switch tag {
        case "InsertRow": self = .insertRow(try container.decode(AxisOp_InsertRow.self, forKey: ContractCodingKey("payload")))
        case "InsertCol": self = .insertCol(try container.decode(AxisOp_InsertCol.self, forKey: ContractCodingKey("payload")))
        case "DeleteRow": self = .deleteRow(try container.decode(AxisOp_DeleteRow.self, forKey: ContractCodingKey("payload")))
        case "DeleteCol": self = .deleteCol(try container.decode(AxisOp_DeleteCol.self, forKey: ContractCodingKey("payload")))
        case "RestoreRow": self = .restoreRow(try container.decode(AxisOp_RestoreRow.self, forKey: ContractCodingKey("payload")))
        case "RestoreCol": self = .restoreCol(try container.decode(AxisOp_RestoreCol.self, forKey: ContractCodingKey("payload")))
        default: throw contractUnknownVariant("AxisOp", tag, decoder.codingPath)
        }
    }

    public func encode(to encoder: any Encoder) throws {
        var container = encoder.container(keyedBy: ContractCodingKey.self)
        switch self {
        case .insertRow(let value):
            try container.encode("InsertRow", forKey: ContractCodingKey("name"))
            try container.encode(value, forKey: ContractCodingKey("payload"))
        case .insertCol(let value):
            try container.encode("InsertCol", forKey: ContractCodingKey("name"))
            try container.encode(value, forKey: ContractCodingKey("payload"))
        case .deleteRow(let value):
            try container.encode("DeleteRow", forKey: ContractCodingKey("name"))
            try container.encode(value, forKey: ContractCodingKey("payload"))
        case .deleteCol(let value):
            try container.encode("DeleteCol", forKey: ContractCodingKey("name"))
            try container.encode(value, forKey: ContractCodingKey("payload"))
        case .restoreRow(let value):
            try container.encode("RestoreRow", forKey: ContractCodingKey("name"))
            try container.encode(value, forKey: ContractCodingKey("payload"))
        case .restoreCol(let value):
            try container.encode("RestoreCol", forKey: ContractCodingKey("name"))
            try container.encode(value, forKey: ContractCodingKey("payload"))
        }
    }
}

