/// A cell, by row and column id. An implicit id is a 0-based position
/// (`"3"` is the fourth row until rows move); the client places ids with the
/// sheet's layout (`get_layouts`).
public struct Cell: Codable, Sendable, Equatable {
    public var id: String
    public var sheetId: String
    public var rowId: String
    public var colId: String
    /// As stored: references name rows and columns by id.
    public var rawValue: String
    public var computedValue: String
    public var format: String
    public var updatedAt: UInt64
    /// Member id of whoever last changed the cell; empty for a cell last
    /// written before the activity log existed.
    public var lastEditor: String
    public var lastEditedAt: UInt64

    public init(id: String, sheetId: String, rowId: String, colId: String, rawValue: String, computedValue: String, format: String, updatedAt: UInt64, lastEditor: String, lastEditedAt: UInt64) {
        self.id = id
        self.sheetId = sheetId
        self.rowId = rowId
        self.colId = colId
        self.rawValue = rawValue
        self.computedValue = computedValue
        self.format = format
        self.updatedAt = updatedAt
        self.lastEditor = lastEditor
        self.lastEditedAt = lastEditedAt
    }

    enum CodingKeys: String, CodingKey {
        case id
        case sheetId = "sheet_id"
        case rowId = "row_id"
        case colId = "col_id"
        case rawValue = "raw_value"
        case computedValue = "computed_value"
        case format
        case updatedAt = "updated_at"
        case lastEditor = "last_editor"
        case lastEditedAt = "last_edited_at"
    }
}

