public indirect enum CellOp: Codable, Sendable, Equatable {
    case set(CellOp_Set)
    case format(CellOp_Format)
    case clear(CellOp_Clear)

    public init(from decoder: any Decoder) throws {
        let container = try decoder.container(keyedBy: ContractCodingKey.self)
        let tag = try container.decode(String.self, forKey: ContractCodingKey("name"))
        switch tag {
        case "Set": self = .set(try container.decode(CellOp_Set.self, forKey: ContractCodingKey("payload")))
        case "Format": self = .format(try container.decode(CellOp_Format.self, forKey: ContractCodingKey("payload")))
        case "Clear": self = .clear(try container.decode(CellOp_Clear.self, forKey: ContractCodingKey("payload")))
        default: throw contractUnknownVariant("CellOp", tag, decoder.codingPath)
        }
    }

    public func encode(to encoder: any Encoder) throws {
        var container = encoder.container(keyedBy: ContractCodingKey.self)
        switch self {
        case .set(let value):
            try container.encode("Set", forKey: ContractCodingKey("name"))
            try container.encode(value, forKey: ContractCodingKey("payload"))
        case .format(let value):
            try container.encode("Format", forKey: ContractCodingKey("name"))
            try container.encode(value, forKey: ContractCodingKey("payload"))
        case .clear(let value):
            try container.encode("Clear", forKey: ContractCodingKey("name"))
            try container.encode(value, forKey: ContractCodingKey("payload"))
        }
    }
}

