/// One step of a note edit, in the Quill delta shape: keep, insert or delete
/// characters, with formatting on kept or inserted text. Mirrors `DeltaOp`,
/// which has no `AbiType`.
public indirect enum NoteChange: Codable, Sendable, Equatable {
    case retain(NoteChange_Retain)
    case insert(NoteChange_Insert)
    case delete(NoteChange_Delete)

    public init(from decoder: any Decoder) throws {
        let container = try decoder.singleValueContainer()
        if let value = try? container.decode(NoteChange_Retain.self) {
            self = .retain(value)
            return
        }
        if let value = try? container.decode(NoteChange_Insert.self) {
            self = .insert(value)
            return
        }
        if let value = try? container.decode(NoteChange_Delete.self) {
            self = .delete(value)
            return
        }
        throw DecodingError.dataCorruptedError(in: container, debugDescription: "No NoteChange variant matches")
    }

    public func encode(to encoder: any Encoder) throws {
        var container = encoder.singleValueContainer()
        switch self {
        case .retain(let value): try container.encode(value)
        case .insert(let value): try container.encode(value)
        case .delete(let value): try container.encode(value)
        }
    }
}

