public struct Spreadsheet: Codable, Sendable, Equatable {
    /// The workbook's id and creation time, fixed in `init`.
    public var founding: Founding
    /// The workbook's name, set by `init_project`; empty until then. Only
    /// owners write it.
    public var projectName: String
    /// Workbook roles. Its admins are the owners; `viewer` and `commenter`
    /// are named roles. A member with neither and not an owner is an editor.
    public var acl: [String: Bool]
    /// Sheet tabs keyed by sheet id.
    public var sheets: [String: SheetData]
    /// Cell values keyed by `"{sheet_id}|{row_id}|{col_id}"`, so one sheet's
    /// cells are one prefix.
    public var cells: [String: CellData]
    /// Chosen nicknames, one slot per account that only it writes.
    public var members: [String: MemberData]
    /// Added and deleted rows and columns, keyed `"{sheet_id}|r|{id}"` and
    /// `"{sheet_id}|c|{id}"`.
    public var axes: [String: AxisData]
    /// Cell formats, keyed like `cells`.
    public var formats: [String: FormatData]
    /// Named ranges keyed by upper-case name.
    public var names: [String: NamedRangeData]
    /// Who last changed each cell, keyed like `cells`.
    public var cellMeta: [String: CellMeta]
    /// The activity log: each entry owned by its author and never changed.
    public var activity: [String: ActivityData]
    /// Cell comments and replies, keyed by comment id: the author edits and
    /// deletes, owners (the moderators) delete.
    public var comments: [String: CommentData]
    /// Whether a comment's thread is resolved, keyed by comment id. Anyone
    /// in the workbook may resolve, so it is not part of the comment.
    public var resolved: [String: Bool]
    /// Cell notes, keyed like `cells`: rich text that merges concurrent edits
    /// character by character.
    public var notes: [String: [String: Span]]
    /// Protected ranges, keyed by id. Only owners write them.
    public var protections: [String: ProtectionData]
    /// Resized rows and columns, keyed like `axes`.
    public var sizes: [String: SizeData]
    /// Frozen rows and columns per sheet.
    public var views: [String: SheetViewData]
    /// Cell styles, keyed like `cells`.
    public var styles: [String: StyleData]
    /// Conditional formats, colour scales and validations, keyed by id.
    public var rules: [String: RuleData]
    /// Charts, keyed by id.
    public var charts: [String: ChartData]
    /// Files attached to cells, keyed by id: whoever attached one removes
    /// it, and owners (the moderators) may.
    public var attachments: [String: AttachmentData]
    /// Ranges this workbook pushes to others, keyed by id: whoever linked
    /// one stops it, and owners (the moderators) may.
    public var publications: [String: PublicationData]
    /// Ranges pushed here from other workbooks, keyed by linked sheet id.
    public var linked: [String: LinkedData]
    /// Alert rules' last matching cells, keyed by rule id.
    public var alertState: [String: AlertState]

    public init(founding: Founding, projectName: String, acl: [String: Bool], sheets: [String: SheetData], cells: [String: CellData], members: [String: MemberData], axes: [String: AxisData], formats: [String: FormatData], names: [String: NamedRangeData], cellMeta: [String: CellMeta], activity: [String: ActivityData], comments: [String: CommentData], resolved: [String: Bool], notes: [String: [String: Span]], protections: [String: ProtectionData], sizes: [String: SizeData], views: [String: SheetViewData], styles: [String: StyleData], rules: [String: RuleData], charts: [String: ChartData], attachments: [String: AttachmentData], publications: [String: PublicationData], linked: [String: LinkedData], alertState: [String: AlertState]) {
        self.founding = founding
        self.projectName = projectName
        self.acl = acl
        self.sheets = sheets
        self.cells = cells
        self.members = members
        self.axes = axes
        self.formats = formats
        self.names = names
        self.cellMeta = cellMeta
        self.activity = activity
        self.comments = comments
        self.resolved = resolved
        self.notes = notes
        self.protections = protections
        self.sizes = sizes
        self.views = views
        self.styles = styles
        self.rules = rules
        self.charts = charts
        self.attachments = attachments
        self.publications = publications
        self.linked = linked
        self.alertState = alertState
    }

    enum CodingKeys: String, CodingKey {
        case founding
        case projectName = "project_name"
        case acl
        case sheets
        case cells
        case members
        case axes
        case formats
        case names
        case cellMeta = "cell_meta"
        case activity
        case comments
        case resolved
        case notes
        case protections
        case sizes
        case views
        case styles
        case rules
        case charts
        case attachments
        case publications
        case linked
        case alertState = "alert_state"
    }
}

